#include <stdio.h>

int main(void) {
    FILE *fp = fopen("zhangben.txt", "w");
    if (fp == NULL) {
        printf("打不开喵\n");
        return 0;
    }
    fprintf(fp, "第一天 1 条\n");
    fclose(fp);

    fp = fopen("zhangben.txt", "a");
