        printf("打不开喵\n");
        return 0;
    }
    fprintf(fp, "第二天 4 条\n");
    fclose(fp);

    fp = fopen("zhangben.txt", "a");
    if (fp == NULL) {
        printf("打不开喵\n");
        return 0;
    }
    fprintf(fp, "第三天 7 条\n");
    fclose(fp);

    fp = fopen("zhangben.txt", "r");
    if (fp == NULL) {
        printf("读不到喵\n");
        return 0;
    }
    char line[64];
    while (fgets(line, sizeof(line), fp) != NULL) {
        printf("%s", line);
    }
    fclose(fp);
    return 0;
}

